#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
//
// Разбор .claude/workspace.json по контракту движка: дефолты, проверка ключей и типов,
// список репозиториев обходом. Реализация одна на все скрипты .claude/bin/: .mjs импортируют
// модуль, shell-скрипты получают те же значения через lib/workspace.sh, который зовёт
//
//   node .claude/bin/lib/workspace.mjs dump <корень>
//
// и читает строки «K\t<ключ>» (ключ известен), «k\t<ключ>\t<значение>» (скаляр),
// «a\t<ключ>\t<элемент>» (массив, по строке на элемент), «r\t<имя>\t<путь от корня>»
// (репозиторий). Вторая копия дефолтов на sh разошлась бы с этой молча.
//
// Нарушения делятся на сорта. Фатальное — значение непригодно к использованию: JSON
// не разбирается, тип не тот, путь выходит за корень. На нём dump падает с кодом 2, потому что
// скрипт уборки с таким путём в белом списке хуже, чем скрипт, который не запустился.
// Остальное (нет обязательного ключа, лишний ключ, барьер не на своей строке) скрипты
// переживают на дефолтах, а называет его workspace-check.mjs. Непригодная запись раздела tests —
// третий сорт (testsFatal): она останавливает только parallel-tests.mjs, а не каждый скрипт
// с dump, — сломанная команда тестов не повод отказывать worktree-add.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const BARRIERS = ['guard-push', 'guard-kill', 'guard-comments', 'guard-commit-split', 'guard-approval-link'];
// Каталоги — константы, а не ключи: хук без node читал бы ключ на каждой команде Bash.
export const PROJECTS_DIR = 'projects';
export const WORKTREES_DIR = 'worktrees';
export const TASKS_DIR = 'memory/tasks';
const REQUIRED = ['beerpowers'];
const KNOWN = [...REQUIRED, 'ui', 'viewports', 'barriers', 'comments', 'tests'];
export const TEST_MODES = ['split', 'native'];
const TEST_REPO_KEYS = ['mode', 'command', 'files', 'exclude', 'workers', 'env', 'prepare', 'mutate'];
const MUTATE_KEYS = ['command', 'check', 'link', 'copy', 'timeout'];
// Подстановки parallel-tests.mjs и mutants.mjs. Что где допустимо — по режиму: в native
// воркеров создаёт фреймворк, поэтому номера слота {i} и списка файлов {files} у тест-команды
// нет. Мутант гоняется одним процессом на слот, и {i} у него есть в любом режиме.
export const TEST_PLACEHOLDERS = ['i', 'n', 'slots', 'repo', 'dir', 'root', 'tmp', 'junit', 'files', 'filter', 'file', 'env'];
const MUTATE_DENY = { mutate: ['files', 'junit', 'file'], check: ['files', 'junit', 'filter'] };
const TEST_DENY = {
  split: { command: ['filter', 'file'], env: ['files', 'filter', 'file'], prepare: ['files', 'junit', 'filter', 'file'], ...MUTATE_DENY },
  native: { command: ['i', 'files', 'filter', 'file'], env: ['files', 'filter', 'file'], prepare: ['files', 'junit', 'filter', 'file'], ...MUTATE_DENY },
};
export const MUTATE_TIMEOUT_S = 600;
export const placeholdersOf = (s) => [...s.matchAll(/\{([a-z]+)(?::([A-Za-z_][A-Za-z0-9_]*))?\}/g)]
  .map((m) => ({ name: m[1], arg: m[2] }));
export const DEFAULT_VIEWPORTS = [
  { name: 'mobile', width: 375, height: 667, mobile: true },
  { name: 'desktop', width: 1440, height: 900, mobile: false },
];
export const SAFE_NAME = /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/;

const isDir = (p) => {
  try { return fs.statSync(p).isDirectory(); } catch { return false; }
};

export function findRoot(fromDir) {
  if (process.env.WORKSPACE_ROOT) {
    const r = path.resolve(process.env.WORKSPACE_ROOT);
    if (!isDir(r)) throw new Error(`WORKSPACE_ROOT — не каталог: ${process.env.WORKSPACE_ROOT}`);
    return r;
  }
  let d = path.resolve(fromDir);
  for (;;) {
    if (path.basename(d) === '.claude') return path.dirname(d);
    const up = path.dirname(d);
    if (up === d) throw new Error(`не найден каталог .claude/ над ${fromDir} — задай WORKSPACE_ROOT`);
    d = up;
  }
}

export function loadWorkspace(root) {
  const file = path.join(root, '.claude', 'workspace.json');
  const problems = [];
  const fatal = (msg) => problems.push({ fatal: true, msg });
  const soft = (msg) => problems.push({ fatal: false, msg });

  let json = {};
  let raw = '';
  const exists = fs.existsSync(file);
  if (exists) {
    raw = fs.readFileSync(file, 'utf8');
    try {
      json = JSON.parse(raw);
      if (json === null || typeof json !== 'object' || Array.isArray(json)) {
        fatal('workspace.json: корень — не объект');
        json = {};
      }
    } catch (e) {
      fatal(`workspace.json не разбирается: ${e.message}`);
      json = {};
    }
  }

  for (const k of REQUIRED) if (exists && !(k in json)) soft(`нет обязательного ключа ${k}`);
  for (const k of Object.keys(json)) if (!KNOWN.includes(k)) soft(`неизвестный ключ ${k}`);

  const noControl = (key, v) => {
    if (/[\t\r\n]/.test(v)) { fatal(`${key}: табуляция или перевод строки в значении`); return false; }
    return true;
  };
  const str = (key, def) => {
    if (!(key in json)) return def;
    const v = json[key];
    if (typeof v !== 'string') { fatal(`${key}: ждётся строка, получено ${JSON.stringify(v)}`); return def; }
    return noControl(key, v) ? v : def;
  };
  const strList = (key, v, def) => {
    if (v === undefined) return def;
    if (!Array.isArray(v) || v.some((x) => typeof x !== 'string')) { fatal(`${key}: ждётся массив строк`); return def; }
    return v.every((x) => noControl(key, x)) ? v : def;
  };
  // Код всегда лежит в projects/<имя>/, корень workspace — отдельный репозиторий конфигурации
  // команды и памяти: тогда рабочие деревья и артефакты задач не попадают в историю продукта.
  const projectsDir = PROJECTS_DIR;
  const worktreesDir = WORKTREES_DIR;
  const tasksDir = TASKS_DIR;

  const beerpowers = str('beerpowers', '');
  if (exists && 'beerpowers' in json && !/^\d+\.\d+\.\d+$/.test(beerpowers)) soft(`beerpowers: «${beerpowers}» — не версия вида 2.0.0`);
  let ui = false;
  if ('ui' in json) {
    if (typeof json.ui !== 'boolean') fatal(`ui: ждётся true или false, получено ${JSON.stringify(json.ui)}`);
    else ui = json.ui;
  }

  let viewports = DEFAULT_VIEWPORTS;
  if ('viewports' in json) {
    const v = json.viewports;
    const posInt = (x) => Number.isInteger(x) && x > 0;
    if (!Array.isArray(v) || v.length === 0) {
      fatal('viewports: ждётся непустой массив объектов {name, width, height, mobile}');
    } else {
      const parsed = [];
      for (const [i, e] of v.entries()) {
        if (e === null || typeof e !== 'object' || Array.isArray(e)) { fatal(`viewports[${i}]: ждётся объект`); continue; }
        for (const k of Object.keys(e)) if (!['name', 'width', 'height', 'mobile'].includes(k)) soft(`viewports[${i}]: неизвестный ключ ${k}`);
        if (typeof e.name !== 'string' || !SAFE_NAME.test(e.name)) { fatal(`viewports[${i}].name: ждётся имя вида tablet`); continue; }
        if (!posInt(e.width) || !posInt(e.height)) { fatal(`viewports[${i}] «${e.name}»: width и height — целые больше нуля`); continue; }
        if ('mobile' in e && typeof e.mobile !== 'boolean') { fatal(`viewports[${i}].mobile: ждётся true или false`); continue; }
        parsed.push({ name: e.name, width: e.width, height: e.height, mobile: e.mobile === true });
      }
      // Ширина — часть имени скриншота (<роль>-<экран>-<ширина>.png): две записи одной ширины
      // дали бы скриншоты, которые перезаписывают друг друга.
      for (const k of ['name', 'width']) {
        const seen = new Set();
        for (const e of parsed) {
          if (seen.has(e[k])) fatal(`viewports: ${k} «${e[k]}» повторяется`);
          seen.add(e[k]);
        }
      }
      if (parsed.length === v.length) viewports = [...parsed].sort((a, b) => a.width - b.width);
    }
    if (!ui) soft('viewports: задан при ui: false — роли его не читают');
  }

  const barriers = Object.fromEntries(BARRIERS.map((b) => [b, true]));
  if ('barriers' in json) {
    const b = json.barriers;
    if (b === null || typeof b !== 'object' || Array.isArray(b)) {
      fatal('barriers: ждётся объект');
    } else {
      for (const [k, v] of Object.entries(b)) {
        if (k === 'guard-agent-memory') { soft('barriers: guard-agent-memory не выключается и в списке не стоит'); continue; }
        if (!BARRIERS.includes(k)) { soft(`barriers: неизвестный барьер ${k}`); continue; }
        if (typeof v !== 'boolean') { fatal(`barriers.${k}: ждётся true или false`); continue; }
        barriers[k] = v;
        // Хуки читают флаг sed'ом построчно — значение в общей строке они не увидят.
        if (!new RegExp(`^\\s*"${k}"\\s*:\\s*(true|false)\\s*,?\\s*$`, 'm').test(raw)) {
          soft(`barriers.${k}: не на своей строке — хуки читают флаг построчно и его не увидят`);
        }
      }
    }
  }

  const section = (key, inner) => {
    if (!(key in json)) return undefined;
    const s = json[key];
    if (s === null || typeof s !== 'object' || Array.isArray(s)) { fatal(`${key}: ждётся объект`); return undefined; }
    for (const k of Object.keys(s)) if (k !== inner) soft(`${key}: неизвестный ключ ${k}`);
    return s[inner];
  };
  const excludeDirs = strList('comments.excludeDirs', section('comments', 'excludeDirs'), []);

  let repos = [];
  const base = path.join(root, projectsDir);
  if (isDir(base)) {
    repos = fs.readdirSync(base, { withFileTypes: true })
      .filter((e) => e.isDirectory() && fs.existsSync(path.join(base, e.name, '.git')))
      .map((e) => ({ name: e.name, path: `${projectsDir}/${e.name}` }))
      .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  }

  // guard-comments применяет запись только к репозиторию из её пути: запись другой формы
  // не действует нигде, и сказать об этом может только проверка.
  for (const d of excludeDirs) {
    const m = d.replace(/\/+$/, '').match(new RegExp(`^${projectsDir.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/([^/]+)/.+`));
    if (!m) soft(`comments.excludeDirs: «${d}» — ждётся путь ${projectsDir}/<репо>/<каталог>, запись не действует`);
    else if (!repos.some((r) => r.name === m[1])) soft(`comments.excludeDirs: «${d}» — репозитория «${m[1]}» в ${projectsDir}/ нет`);
  }

  const tests = parseTests(json, repos, (msg) => problems.push({ fatal: false, testsFatal: true, msg }), soft);

  const config = {
    beerpowers, projectsDir, worktreesDir, tasksDir, ui,
    ...Object.fromEntries(BARRIERS.map((b) => [`barriers.${b}`, barriers[b]])),
    'comments.excludeDirs': excludeDirs,
  };
  return { root, file, exists, config, viewports, viewportsDefault: !('viewports' in json), repos, tests, problems };
}

// Раздел tests — настройки parallel-tests.mjs: лимит слотов машины по умолчанию и прогон
// каждого репозитория. Непригодная запись (нет команды, чужая подстановка) прогон
// останавливает: он запустил бы не те тесты или все тесты в каждом воркере.
function parseTests(json, repos, fatal, soft) {
  const empty = { slots: null, repos: {} };
  if (!('tests' in json)) return empty;
  const t = json.tests;
  const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
  if (!isObj(t)) { fatal('tests: ждётся объект'); return empty; }
  for (const k of Object.keys(t)) if (!['slots', 'repos'].includes(k)) soft(`tests: неизвестный ключ ${k}`);
  const posInt = (x) => Number.isInteger(x) && x > 0;
  let slots = null;
  if ('slots' in t) {
    if (!posInt(t.slots)) fatal(`tests.slots: ждётся целое больше нуля, получено ${JSON.stringify(t.slots)}`);
    else slots = t.slots;
  }
  const out = {};
  if (!('repos' in t)) { soft('tests: нет repos — parallel-tests.mjs нечего запускать'); return { slots, repos: out }; }
  if (!isObj(t.repos)) { fatal('tests.repos: ждётся объект «имя репозитория → настройки прогона»'); return { slots, repos: out }; }
  for (const [name, e] of Object.entries(t.repos)) {
    const key = `tests.repos.${name}`;
    if (!SAFE_NAME.test(name)) { fatal(`${key}: имя репозитория — [A-Za-z0-9_.-]`); continue; }
    if (!isObj(e)) { fatal(`${key}: ждётся объект`); continue; }
    if (!repos.some((r) => r.name === name)) soft(`${key}: репозитория «${name}» в ${PROJECTS_DIR}/ нет`);
    for (const k of Object.keys(e)) if (!TEST_REPO_KEYS.includes(k)) soft(`${key}: неизвестный ключ ${k}`);
    const mode = e.mode === undefined ? 'split' : e.mode;
    if (!TEST_MODES.includes(mode)) { fatal(`${key}.mode: ждётся ${TEST_MODES.join(' или ')}`); continue; }
    let ok = true;
    const bad = (msg) => { fatal(`${key}${msg}`); ok = false; };
    const text = (k, v) => {
      if (typeof v !== 'string' || v.trim() === '') { bad(`.${k}: ждётся непустая строка`); return false; }
      if (/[\r\n]/.test(v)) { bad(`.${k}: перевод строки в значении`); return false; }
      return true;
    };
    const holders = (k, v, field) => {
      for (const p of placeholdersOf(v)) {
        if (!TEST_PLACEHOLDERS.includes(p.name)) bad(`.${k}: неизвестная подстановка {${p.name}}`);
        else if (TEST_DENY[mode][field].includes(p.name)) bad(`.${k}: {${p.name}} ${field in MUTATE_DENY ? 'здесь' : `в режиме ${mode}`} не подставляется`);
        else if (p.name === 'env' && !p.arg) bad(`.${k}: {env} без имени переменной — {env:ИМЯ}`);
      }
    };
    if (!('command' in e)) bad('.command: нет команды прогона');
    else if (text('command', e.command)) {
      holders('command', e.command, 'command');
      if (mode === 'split' && !placeholdersOf(e.command).some((p) => p.name === 'files')) {
        bad('.command: в режиме split нет {files} — каждый воркер прогнал бы все тесты');
      }
    }
    const list = (k, obj = e) => {
      if (!(k in obj)) return [];
      const v = obj[k];
      if (!Array.isArray(v) || v.some((x) => typeof x !== 'string' || x === '')) { bad(`.${k}: ждётся массив путей или масок`); return []; }
      for (const x of v) {
        if (x.startsWith('/') || /^[A-Za-z]:/.test(x) || x.split('/').includes('..')) bad(`.${k}: «${x}» — маска выходит за репозиторий`);
        if (x.includes('\\')) bad(`.${k}: «${x}» — разделитель путей прямой слэш`);
      }
      return v;
    };
    const files = list('files');
    const exclude = list('exclude');
    if (mode === 'split' && files.length === 0) bad('.files: в режиме split нужна маска тестовых файлов');
    if (mode === 'native') for (const k of ['files', 'exclude']) if (k in e) soft(`${key}.${k}: в режиме native не читается — набор файлов задаёт конфиг фреймворка`);
    let workers = null;
    if ('workers' in e) {
      if (!posInt(e.workers)) bad(`.workers: ждётся целое больше нуля`);
      else workers = e.workers;
    }
    const env = {};
    if ('env' in e) {
      if (!isObj(e.env)) bad('.env: ждётся объект «переменная → значение»');
      else {
        for (const [k, v] of Object.entries(e.env)) {
          if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(k)) { bad(`.env: «${k}» — не имя переменной`); continue; }
          if (typeof v !== 'string' || /[\r\n]/.test(v)) { bad(`.env.${k}: ждётся строка в одну строку`); continue; }
          holders(`env.${k}`, v, 'env');
          env[k] = v;
        }
      }
    }
    let prepare = null;
    if ('prepare' in e && text('prepare', e.prepare)) { holders('prepare', e.prepare, 'prepare'); prepare = e.prepare; }
    const all = [e.command, ...Object.values(env)].filter((v) => typeof v === 'string');
    if (ok && !all.some((v) => placeholdersOf(v).some((p) => p.name === 'junit'))) {
      soft(`${key}: нет {junit} ни в команде, ни в env — счёт тестов и раскладка по времени недоступны`);
    }
    // mutate — как гонять мутант в копии дерева: команда с фильтром теста, проверка файла
    // после замены, что из рабочего дерева ссылкой (зависимости), что копией (env-файлы).
    let mutate = null;
    if ('mutate' in e) {
      const m = e.mutate;
      if (!isObj(m)) bad('.mutate: ждётся объект');
      else {
        for (const k of Object.keys(m)) if (!MUTATE_KEYS.includes(k)) soft(`${key}.mutate: неизвестный ключ ${k}`);
        if (!('command' in m)) bad('.mutate.command: нет команды прогона мутанта');
        else if (text('mutate.command', m.command)) {
          holders('mutate.command', m.command, 'mutate');
          if (!placeholdersOf(m.command).some((p) => p.name === 'filter')) bad('.mutate.command: нет {filter} — мутант гонял бы весь набор');
        }
        let check = null;
        if ('check' in m && text('mutate.check', m.check)) {
          holders('mutate.check', m.check, 'check');
          if (!placeholdersOf(m.check).some((p) => p.name === 'file')) bad('.mutate.check: нет {file} — проверять нечего');
          check = m.check;
        }
        let timeout = MUTATE_TIMEOUT_S;
        if ('timeout' in m) {
          if (!posInt(m.timeout)) bad('.mutate.timeout: ждётся целое число секунд больше нуля');
          else timeout = m.timeout;
        }
        const link = list('mutate.link', { 'mutate.link': m.link ?? [] });
        const copy = list('mutate.copy', { 'mutate.copy': m.copy ?? [] });
        for (const x of [...link, ...copy]) if (/[*?]/.test(x)) bad(`.mutate: «${x}» — путь, а не маска`);
        mutate = { command: m.command, check, link, copy, timeout };
      }
    }
    if (ok) out[name] = { mode, command: e.command, files, exclude, workers, env, prepare, mutate };
  }
  return { slots, repos: out };
}

function dump(root) {
  const ws = loadWorkspace(root);
  const fatals = ws.problems.filter((p) => p.fatal);
  if (fatals.length) {
    for (const p of fatals) process.stderr.write(`.claude/workspace.json: ${p.msg}\n`);
    process.exit(2);
  }
  const out = [];
  for (const [k, v] of Object.entries(ws.config)) {
    out.push(`K\t${k}`);
    if (Array.isArray(v)) for (const x of v) out.push(`a\t${k}\t${x}`);
    else out.push(`k\t${k}\t${v}`);
  }
  for (const r of ws.repos) out.push(`r\t${r.name}\t${r.path}`);
  process.stdout.write(out.join('\n') + '\n');
}

const isMain = (() => {
  try {
    return Boolean(process.argv[1]) && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));
  } catch { return false; }
})();

if (isMain) {
  const [cmd, root] = process.argv.slice(2);
  if (cmd !== 'dump' || !root) {
    process.stderr.write('использование: node lib/workspace.mjs dump <корень workspace>\n');
    process.exit(2);
  }
  if (!isDir(root)) {
    process.stderr.write(`корень workspace — не каталог: ${root}\n`);
    process.exit(2);
  }
  dump(path.resolve(root));
}
